using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.Rendering;
using UnityEngine.UI;

namespace Rokas.Presentation
{
    public static class WorkbenchWeaponMeshLibrary
    {
        public const int SuppliedFbxOriginalVertexCount = 48858;
        public const int SuppliedFbxOriginalPolygonCount = 97712;
        public const string SuppliedFbxName = "metal+sword+3d+model.fbx";

        private const string TwoHandedMeshGzip = "";
        private const string DaggerMeshGzip = "";

        public static Mesh Create(WorkbenchWeaponKind kind)
        {
            return kind == WorkbenchWeaponKind.Dagger
                ? WorkbenchPremiumDaggerMesh.Create()
                : WorkbenchPremiumSwordMesh.Create();
        }

        private static Mesh DecodeTwoHanded()
        {
            using var stream = Open(TwoHandedMeshGzip);
            using var reader = new BinaryReader(stream);
            int vertexCount = reader.ReadInt32();
            int faceCount = reader.ReadInt32();
            Vector3[] vertices = ReadVertices(reader, vertexCount);
            int[] triangles = ReadTriangles(reader, faceCount);

            float minY = float.PositiveInfinity;
            float maxY = float.NegativeInfinity;
            for (int index = 0; index < vertices.Length; index++)
            {
                minY = Mathf.Min(minY, vertices[index].y);
                maxY = Mathf.Max(maxY, vertices[index].y);
            }
            float height = Mathf.Max(.0001f, maxY - minY);
            var blade = new List<int>(triangles.Length);
            var accent = new List<int>(triangles.Length / 5);
            var grip = new List<int>(triangles.Length / 5);
            for (int index = 0; index < triangles.Length; index += 3)
            {
                float centroidY =
                    (vertices[triangles[index]].y +
                     vertices[triangles[index + 1]].y +
                     vertices[triangles[index + 2]].y) / 3f;
                float normalizedY = (centroidY - minY) / height;
                List<int> target = normalizedY < .72f ? blade :
                    normalizedY < .83f ? accent : grip;
                target.Add(triangles[index]);
                target.Add(triangles[index + 1]);
                target.Add(triangles[index + 2]);
            }

            var mesh = new Mesh { name = "WorkbenchTwoHanded_FbxDerived_Premium" };
            mesh.indexFormat = vertexCount > ushort.MaxValue ? IndexFormat.UInt32 : IndexFormat.UInt16;
            mesh.vertices = vertices;
            mesh.subMeshCount = 3;
            mesh.SetTriangles(blade, 0, true);
            mesh.SetTriangles(accent, 1, true);
            mesh.SetTriangles(grip, 2, true);
            FinalizePresentationMesh(mesh, vertices);
            return mesh;
        }

        private static Mesh DecodeDagger()
        {
            using var stream = Open(DaggerMeshGzip);
            using var reader = new BinaryReader(stream);
            int vertexCount = reader.ReadInt32();
            int metalFaceCount = reader.ReadInt32();
            int gripFaceCount = reader.ReadInt32();
            Vector3[] vertices = ReadVertices(reader, vertexCount);
            int[] metalTriangles = ReadTriangles(reader, metalFaceCount);
            int[] gripTriangles = ReadTriangles(reader, gripFaceCount);
            var mesh = new Mesh { name = "WorkbenchRitualDagger" };
            mesh.vertices = vertices;
            mesh.subMeshCount = 2;
            mesh.SetTriangles(metalTriangles, 0);
            mesh.SetTriangles(gripTriangles, 1);
            FinalizePresentationMesh(mesh, vertices);
            return mesh;
        }

        private static MemoryStream Open(string base64)
        {
            byte[] compressed = Convert.FromBase64String(base64);
            using var source = new MemoryStream(compressed, false);
            using var gzip = new GZipStream(source, CompressionMode.Decompress);
            var output = new MemoryStream();
            gzip.CopyTo(output);
            output.Position = 0;
            return output;
        }

        private static Vector3[] ReadVertices(BinaryReader reader, int count)
        {
            var vertices = new Vector3[count];
            for (int index = 0; index < count; index++)
            {
                float x = reader.ReadInt16() / 30000f;
                float y = reader.ReadInt16() / 30000f;
                float z = reader.ReadInt16() / 30000f;
                vertices[index] = new Vector3(x, y, z);
            }
            return vertices;
        }

        private static int[] ReadTriangles(BinaryReader reader, int faceCount)
        {
            int[] triangles = new int[faceCount * 3];
            for (int index = 0; index < triangles.Length; index++)
                triangles[index] = reader.ReadUInt16();
            return triangles;
        }

        private static void FinalizePresentationMesh(Mesh mesh, Vector3[] vertices)
        {
            if (!mesh || vertices == null || vertices.Length == 0) return;
            mesh.RecalculateBounds();
            Bounds bounds = mesh.bounds;
            float width = Mathf.Max(bounds.size.x, .0001f);
            float height = Mathf.Max(bounds.size.y, .0001f);
            var uv = new Vector2[vertices.Length];
            for (int index = 0; index < vertices.Length; index++)
            {
                uv[index] = new Vector2(
                    (vertices[index].x - bounds.min.x) / width,
                    (vertices[index].y - bounds.min.y) / height);
            }
            mesh.uv = uv;
            mesh.RecalculateNormals();
            mesh.RecalculateTangents();
            mesh.RecalculateBounds();
        }
    }

    [AddComponentMenu("ROKAS/UI/Workbench Weapon Preview 3D")]
    public sealed class WorkbenchWeaponPreview3D : MonoBehaviour, IBeginDragHandler, IDragHandler, IEndDragHandler
    {
        private const int PreviewLayer = 31;
        private static readonly Vector3 PreviewOrigin = new Vector3(9100f, 9100f, 9100f);

        private RawImage target;
        private RenderTexture renderTexture;
        private GameObject rig;
        private Transform pivot;
        private Camera previewCamera;
        private GameObject weaponObject;
        private Mesh currentMesh;
        private WorkbenchWeaponMaterialSet materials;
        private Quaternion baseRotation;
        private float idleTime;
        private float userYaw;
        private float userPitch;
        private bool userDragging;

        public WorkbenchWeaponKind CurrentKind { get; private set; }
        public bool HasModel => currentMesh != null && weaponObject;
        public int CurrentVertexCount => currentMesh ? currentMesh.vertexCount : 0;
        public int CurrentTriangleCount => currentMesh ? currentMesh.triangles.Length / 3 : 0;
        public Vector3 CurrentMeshBoundsSize => currentMesh ? currentMesh.bounds.size : Vector3.zero;
        public float CurrentCenteringError
        {
            get
            {
                if (!currentMesh || !weaponObject) return float.PositiveInfinity;
                Vector3 scaledCenter = Vector3.Scale(currentMesh.bounds.center, weaponObject.transform.localScale);
                return (weaponObject.transform.localPosition + scaledCenter).magnitude;
            }
        }
        public int ActiveRendererCount => rig ? rig.GetComponentsInChildren<MeshRenderer>(true).Length : 0;
        public int ActivePreviewCameraCount => rig ? rig.GetComponentsInChildren<Camera>(true).Length : 0;
        public bool HasCreatedRenderTexture => renderTexture && renderTexture.IsCreated();
        public int RenderTextureWidth => renderTexture ? renderTexture.width : 0;
        public int RenderTextureHeight => renderTexture ? renderTexture.height : 0;
        public bool HasPremiumSurfaceMaps => materials != null && materials.HasSurfaceMaps;
        public int ActiveLightCount => rig ? rig.GetComponentsInChildren<Light>(true).Length : 0;
        public string CurrentMeshName => currentMesh ? currentMesh.name : string.Empty;
        public float UserYaw => userYaw;
        public float UserPitch => userPitch;
        public bool IsUserDragging => userDragging;
        public string CurrentSource => CurrentKind == WorkbenchWeaponKind.TwoHanded
            ? WorkbenchWeaponMeshLibrary.SuppliedFbxName + " / premium authored heavy greatsword presentation mesh"
            : "ROKAS premium authored ritual dagger mesh";

        public void Initialize(RawImage image, WorkbenchWeaponKind initial)
        {
            target = image ?? throw new ArgumentNullException(nameof(image));
            EnsureRig();
            SetWeapon(initial);
            RenderNow();
        }

        public void SetWeapon(WorkbenchWeaponKind kind)
        {
            EnsureRig();
            if (weaponObject)
            {
                weaponObject.transform.SetParent(null, false);
                weaponObject.SetActive(false);
                WorkbenchWeaponVisualFactory.DestroyObject(weaponObject);
                weaponObject = null;
            }
            if (currentMesh)
            {
                WorkbenchWeaponVisualFactory.DestroyObject(currentMesh);
                currentMesh = null;
            }

            currentMesh = WorkbenchWeaponMeshLibrary.Create(kind);
            currentMesh.hideFlags = HideFlags.HideAndDontSave;
            weaponObject = new GameObject(kind == WorkbenchWeaponKind.TwoHanded
                ? "WorkbenchTwoHanded3D" : "WorkbenchDagger3D");
            weaponObject.hideFlags = HideFlags.HideAndDontSave;
            weaponObject.layer = PreviewLayer;
            weaponObject.transform.SetParent(pivot, false);

            var filter = weaponObject.AddComponent<MeshFilter>();
            filter.sharedMesh = currentMesh;
            var renderer = weaponObject.AddComponent<MeshRenderer>();
            WorkbenchWeaponVisualFactory.ConfigureRenderer(renderer, kind, materials);

            CurrentKind = kind;
            WorkbenchWeaponVisualFactory.ApplyPose(weaponObject.transform, currentMesh, kind, false);
            baseRotation = WorkbenchWeaponVisualFactory.PresentationRotation(kind, false);
            pivot.localRotation = baseRotation;
            pivot.localPosition = Vector3.zero;
            idleTime = 0f;
            userYaw = 0f;
            userPitch = 0f;
            userDragging = false;
            RenderNow();
        }

        public void RenderNow()
        {
            if (!previewCamera || SystemInfo.graphicsDeviceType == GraphicsDeviceType.Null) return;
            previewCamera.Render();
        }

        private void LateUpdate()
        {
            if (!pivot || !weaponObject) return;
            idleTime += Time.unscaledDeltaTime;
            if (!userDragging)
            {
                userYaw = Mathf.Lerp(userYaw, 0f, Time.unscaledDeltaTime * 1.35f);
                userPitch = Mathf.Lerp(userPitch, 0f, Time.unscaledDeltaTime * 1.35f);
            }

            float yaw = Mathf.Sin(idleTime * .30f) * 7.5f + userYaw;
            float pitch = Mathf.Cos(idleTime * .39f) * 1.25f + userPitch;
            float roll = Mathf.Sin(idleTime * .25f) * .65f;
            pivot.localRotation = baseRotation * Quaternion.Euler(pitch, yaw, roll);
            pivot.localPosition = new Vector3(0, Mathf.Sin(idleTime * .58f) * .015f, 0);
            RenderNow();
        }

        public void OnBeginDrag(PointerEventData eventData)
        {
            if (!weaponObject) return;
            userDragging = true;
        }

        public void OnDrag(PointerEventData eventData)
        {
            if (!userDragging || eventData == null) return;
            userYaw = Mathf.Clamp(userYaw - eventData.delta.x * .10f, -24f, 24f);
            userPitch = Mathf.Clamp(userPitch + eventData.delta.y * .065f, -8f, 8f);
        }

        public void OnEndDrag(PointerEventData eventData)
        {
            userDragging = false;
        }

        private void EnsureRig()
        {
            if (rig) return;

            renderTexture = new RenderTexture(1024, 1024, 24, RenderTextureFormat.ARGB32)
            {
                name = "WorkbenchWeaponPreviewRT",
                antiAliasing = 4,
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp,
                hideFlags = HideFlags.HideAndDontSave
            };
            renderTexture.Create();
            target.texture = renderTexture;
            target.color = Color.white;
            target.raycastTarget = true;

            rig = new GameObject("WorkbenchWeaponPreviewRig");
            rig.hideFlags = HideFlags.HideAndDontSave;
            rig.transform.position = PreviewOrigin;

            var pivotObject = new GameObject("WeaponPivot");
            pivotObject.hideFlags = HideFlags.HideAndDontSave;
            pivotObject.layer = PreviewLayer;
            pivotObject.transform.SetParent(rig.transform, false);
            pivot = pivotObject.transform;

            var cameraObject = new GameObject("PreviewCamera");
            cameraObject.hideFlags = HideFlags.HideAndDontSave;
            cameraObject.layer = PreviewLayer;
            cameraObject.transform.SetParent(rig.transform, false);
            cameraObject.transform.localPosition = new Vector3(0, 0, -5.9f);
            cameraObject.transform.localRotation = Quaternion.identity;
            previewCamera = cameraObject.AddComponent<Camera>();
            previewCamera.enabled = false;
            previewCamera.clearFlags = CameraClearFlags.SolidColor;
            previewCamera.backgroundColor = new Color(0, 0, 0, 0);
            previewCamera.cullingMask = 1 << PreviewLayer;
            previewCamera.fieldOfView = 23f;
            previewCamera.nearClipPlane = .1f;
            previewCamera.farClipPlane = 20f;
            previewCamera.allowHDR = false;
            previewCamera.targetTexture = renderTexture;

            materials = WorkbenchWeaponVisualFactory.CreateMaterials();
            WorkbenchWeaponVisualFactory.AddDirectionalLight(rig.transform, "WorkbenchKey",
                new Color(.86f, .91f, .96f), 1.22f, new Vector3(22f, -28f, 0f));
            WorkbenchWeaponVisualFactory.AddDirectionalLight(rig.transform, "WorkbenchFill",
                new Color(.46f, .57f, .68f), .34f, new Vector3(-18f, 40f, 0f));
            WorkbenchWeaponVisualFactory.AddDirectionalLight(rig.transform, "WorkbenchRim",
                new Color(.08f, .55f, .94f), .72f, new Vector3(14f, 150f, 0f));
        }

        private void OnDestroy()
        {
            if (target) target.texture = null;
            if (weaponObject) WorkbenchWeaponVisualFactory.DestroyObject(weaponObject);
            if (currentMesh) WorkbenchWeaponVisualFactory.DestroyObject(currentMesh);
            if (rig) WorkbenchWeaponVisualFactory.DestroyObject(rig);
            materials?.Dispose();
            materials = null;
            if (renderTexture)
            {
                renderTexture.Release();
                WorkbenchWeaponVisualFactory.DestroyObject(renderTexture);
            }
        }
    }
}
